// Domain enums — kept in lockstep with the SQL enums in 0001_init.sql.
// The full Database type is generated by `npm run db:types` into
// ./database.types.ts; that is the authoritative source for table row shapes.
// This file holds enums and convenience aliases that are used widely.

export type OperatorStatus = 'pending' | 'active' | 'suspended';
export type OperatorUserRole = 'admin' | 'manager' | 'picker' | 'lead';
export type AuctionStatus = 'draft' | 'scheduled' | 'live' | 'closed' | 'canceled';
export type LotStatus =
  | 'draft'
  | 'scheduled'
  | 'live'
  | 'won'
  | 'unsold'
  | 'canceled'
  | 'relisted'
  // 0475: the sale was fully refunded and the item never left; it waits to be
  // relisted with a manager PIN (relist_refunded_lot).
  | 'refunded';
export type LotCondition = 'appears_new' | 'open_box' | 'good' | 'as_is';
export type InvoiceStatus =
  | 'pending'
  | 'paid'
  | 'refunded'
  | 'partially_refunded'
  | 'canceled';
export type PickupStatus =
  | 'pending'
  | 'scheduled'
  | 'completed'
  | 'no_show'
  | 'forfeited';
export type BinAssignmentStatus = 'staged' | 'picked_up' | 'returned_to_floor';
export type DisputeStatus = 'open' | 'resolved' | 'denied';

// Bin coordinate on a warehouse floor plan
export type BinCoordinate = {
  binId: string;
  code: string;
  xPx: number;
  yPx: number;
};
